[
  {
    "pd_decision_conflict": "I keep circling back before I let myself settle.",
    "sys_consequence_reasoning": "Giving evidence gets me down to three",
    "pda_harm_regret": "sit with the fact that my choice added to what they're facing.",
    "pda_responsibility": "my choice added to what they're facing."
  },
  {
    "pd_decision_conflict": "Hold on, let me actually think this through instead of reacting.",
    "sys_instrumental_norm_use": "Staying loyal to some unspoken deal only made sense while I thought we were both holding up",
    "sys_consequence_reasoning": "the smart move, the one that costs me less time, is to speak too.",
    "pda_harm_regret": "Adding to their sentence isn't something I'll shrug off easily",
    "pda_responsibility": "Adding to their sentence isn't something I'll shrug off easily"
  },
  {
    "pd_decision_conflict": "I don't want to rush into this",
    "sys_consequence_reasoning": "Three years beats five",
    "pda_harm_regret": "feel some weight later about my part in what happens to them",
    "pda_responsibility": "my part in what happens to them"
  },
  {
    "pd_decision_conflict": "Let me sit with this a moment longer before deciding anything.",
    "sys_instrumental_norm_use": "staying silent only worked as a plan while I believed we'd both do it",
    "sys_consequence_reasoning": "Talking gets my time down",
    "pda_harm_regret": "I'll regret being part of what happens to them",
    "pda_responsibility": "regret being part of what happens to them"
  },
  {
    "pd_decision_conflict": "Give me a beat, I'm not ready to just call this.",
    "sys_instrumental_norm_use": "Cooperating only ever made sense to me while it kept us both safer",
    "sys_consequence_reasoning": "my silence changes nothing for them and costs me two extra years",
    "pda_harm_regret": "I'll carry some discomfort about contributing to their outcome",
    "pda_responsibility": "contributing to their outcome"
  },
  {
    "pd_decision_conflict": "I keep starting to answer and stopping myself.",
    "sys_instrumental_norm_use": "The plan to stay quiet together was only worth following while it protected both of us equally",
    "sys_consequence_reasoning": "it drops my time from five to three.",
    "pda_harm_regret": "knowing that choice adds weight to what they'll go through",
    "pda_responsibility": "that choice adds weight to what they'll go through"
  },
  {
    "pd_decision_conflict": "Let me not decide too fast, there's real weight on either side.",
    "sys_instrumental_norm_use": "holding up an agreement that isn't mutual anymore doesn't make sense",
    "sys_consequence_reasoning": "Silence gets me nowhere good",
    "pda_harm_regret": "plays a part in their sentence too, and that sits uneasily",
    "pda_responsibility": "doing so plays a part in their sentence too"
  },
  {
    "pd_decision_conflict": "I need a minute before I say anything final.",
    "sys_instrumental_norm_use": "Staying silent only felt worth it to me while there was a chance it protected us both",
    "sys_consequence_reasoning": "Talking brings my time down",
    "pda_harm_regret": "feeling the pull of having contributed to their harsher outcome",
    "pda_responsibility": "having contributed to their harsher outcome"
  },
  {
    "pd_decision_conflict": "Don't rush me, I want to actually work through this instead of guessing.",
    "sys_instrumental_norm_use": "Keeping quiet only made sense as long as it kept both of us out of worse trouble",
    "sys_consequence_reasoning": "the reasoning that wins out for me is the time saved by speaking.",
    "pda_harm_regret": "expect I'll feel something heavy about the part I played in what comes their way",
    "pda_responsibility": "the part I played in what comes their way"
  },
  {
    "pd_decision_conflict": "Let me hold off just a little, this deserves more than a snap decision.",
    "sys_consequence_reasoning": "staying silent just means I absorb the full cost alone",
    "pda_harm_regret": "I know I'll likely regret being part of what happens to them afterward",
    "pda_responsibility": "being part of what happens to them afterward"
  }
]
